/// <summary>
/// CB166_SalesOrderSubstitutes
/// The <c>METSalesItemSubstituteSearch_Disabled</c> child class is responsible for the substitutes search with customer substitutions enabled = No.
/// </summary>
class METSalesItemSubstituteSearch_Disabled extends METSalesItemSubstituteSearch
{
}

Method.Source:
    /// <summary>
    /// search for a never first, else check the item status and search for replacement or OOS
    /// </summary>
    /// <returns>The found <c>METSalesItemSubstitute</c> record; otherwise, null.</returns>
    public METSalesItemSubstitute search()
    {
        METSalesItemSubstitute ret;

        // search for Never first
        this.parmSubstitutionCodeSet(this.createSubstitutionCodeSet(METSalesItemSubstitutionCode::Never));
        ret = super();

        if (!ret)
        {
            // search for a replacement
            this.parmSubstitutionCodeSet(this.createSubstitutionCodeSet(METSalesItemSubstitutionCode::Replacement));
            ret = super();

            if (!ret || !MetItemSiteSettingsSetup::isItemStatus(itemid, inventDim.InventSiteId, METConstants::Deleted))
            {
                // else search for OOS
                this.parmSubstitutionCodeSet(this.createSubstitutionCodeSet(METSalesItemSubstitutionCode::OutOfStock));
                ret = super();
            }
        }

        return ret;
    }
